import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addYears_TriageGen0Test {

    @Test
    public void testAddYearsPositive() {
        // Test adding positive years to a standard date
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 12, 0, 0, 0);
        dt.addYears(5);
        assertEquals(2025, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddYearsNegative() {
        // Test adding negative years (subtracting)
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 12, 0, 0, 0);
        dt.addYears(-5);
        assertEquals(2015, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddYearsZero() {
        // Test adding zero years
        MutableDateTime dt = new MutableDateTime(2020, 5, 15, 10, 30, 0, 0);
        long originalMillis = dt.getMillis();
        dt.addYears(0);
        assertEquals(originalMillis, dt.getMillis());
        assertEquals(2020, dt.getYear());
    }

    @Test
    public void testAddYearsLeapYearEnd() {
        // Test adding years to Leap Day (Feb 29)
        // Adding 1 year to 2020-02-29 should result in 2021-02-28
        MutableDateTime dt = new MutableDateTime(2020, 2, 29, 0, 0, 0, 0);
        dt.addYears(1);
        assertEquals(2021, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddYearsToLeapYear() {
        // Test adding years that land on a leap year
        MutableDateTime dt = new MutableDateTime(2019, 2, 28, 0, 0, 0, 0);
        dt.addYears(1);
        assertEquals(2020, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(29, dt.getDayOfMonth());
    }

    @Test
    public void testAddYearsLargeValue() {
        // Test adding a very large number of years
        MutableDateTime dt = new MutableDateTime(1, 1, 1, 0, 0, 0, 0);
        dt.addYears(1000);
        assertEquals(1001, dt.getYear());
    }

    @Test
    public void testAddYearsBoundaryEra() {
        // Test adding years across era boundaries (if applicable to the chronology)
        // Using a standard date to ensure stability
        MutableDateTime dt = new MutableDateTime(1, 1, 1, 0, 0, 0, 0);
        dt.addYears(-1);
        // Note: Joda-Time handles BCE/CE transitions via Chronology. 
        // We simply verify the method executes and modifies the state.
        assertNotEquals(1, dt.getYear());
    }
}
